INSERT INTO _migration_614_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_nuclear_s3_001', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which type of nuclear radiation is the most strongly ionising?', 'multiple_choice', NULL, '["A. Beta (β) radiation","B. Gamma (γ) radiation","C. Alpha (α) radiation","D. X-rays"]', 'C', 'Alpha particles are helium nuclei with charge +2 and a relatively large mass, so they collide frequently and ionise matter most strongly — which is also why they are the least penetrating. Beta and gamma ionise progressively less, and X-rays, like gamma rays, are weakly ionising electromagnetic waves. Therefore the correct answer is C: Alpha (α) radiation.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_nuclear_s3_002', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A nucleus of uranium is represented as ²³⁵₉₂U. How many neutrons does this nucleus contain?', 'multiple_choice', NULL, '["A. 92","B. 235","C. 327","D. 143"]', 'D', 'The number of neutrons is the mass (nucleon) number minus the proton number: 235 − 92 = 143. (92 is the number of protons, 235 is the total number of protons and neutrons, and 327 adds the two numbers instead of subtracting.) Therefore the correct answer is D: 143.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_nuclear_s3_003', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'What is meant by the half-life of a radioactive isotope?', 'multiple_choice', NULL, '["A. The time taken for half of the undecayed nuclei in a sample to decay","B. The time taken for all the nuclei in a sample to decay","C. Half the time taken for the sample to decay completely","D. The time taken for a single nucleus to decay"]', 'A', 'Radioactive decay is a random process, so half-life is defined statistically: after one half-life, half of the original undecayed nuclei remain and the activity of the sample has halved. A sample never decays completely in a fixed time, and no single nucleus has its own predictable decay time. Therefore the correct answer is A: The time taken for half of the undecayed nuclei in a sample to decay.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_nuclear_s3_004', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which statement about nuclear fusion is correct?', 'multiple_choice', NULL, '["A. A heavy nucleus splits into two lighter nuclei, releasing energy","B. Two light nuclei join together to form a heavier nucleus, releasing energy","C. It takes place only inside nuclear reactors on Earth","D. It is a chemical reaction between hydrogen atoms"]', 'B', 'Fusion joins light nuclei such as hydrogen isotopes to form heavier nuclei like helium, converting some mass into energy; it powers the Sun and other stars. Splitting a heavy nucleus is fission, fusion happens naturally in stars rather than only in reactors, and it is a nuclear process — far more energetic than any chemical reaction. Therefore the correct answer is B: Two light nuclei join together to form a heavier nucleus, releasing energy.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_nuclear_s3_005', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A radioactive isotope has a half-life of 8 days. A sample of the isotope has an initial activity of 640 Bq. What is the activity of the sample after 24 days?', 'multiple_choice', NULL, '["A. 160 Bq","B. 213 Bq","C. 80 Bq","D. 27 Bq"]', 'C', '24 days is 24 ÷ 8 = 3 half-lives, so the activity halves three times: 640 → 320 → 160 → 80 Bq. (160 Bq stops after only two half-lives; 213 Bq simply divides 640 by 3; 27 Bq divides 640 by 24.) Therefore the correct answer is C: 80 Bq.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_nuclear_s3_006', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'In a nuclear fission reactor, what is the function of the moderator?', 'multiple_choice', NULL, '["A. It absorbs excess neutrons to control the rate of the reaction","B. It transfers thermal energy from the core to the turbines","C. It prevents radiation from escaping the reactor","D. It slows down the fast neutrons so that they can go on to cause further fission"]', 'D', 'Fission is sustained by slow (thermal) neutrons, so the moderator — graphite or water — slows the fast neutrons released by fission so they can trigger further fission of ²³⁵U. Absorbing excess neutrons is the job of the control rods, transferring thermal energy is the role of the coolant, and containment is provided by the shielding. Therefore the correct answer is D: It slows down the fast neutrons so that they can go on to cause further fission.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_nuclear_s3_007', 'topic_igcse_physics_nuclear', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Radioactive isotopes have many important uses in medicine and industry.', 'structured', NULL, NULL, '(a) Alpha is the most strongly ionising but least penetrating, stopped by paper or a few centimetres of air; beta is less ionising and more penetrating, stopped by a few millimetres of aluminium; gamma is the least ionising and most penetrating, requiring thick lead or concrete to reduce it significantly. (b) The activity of the tracer falls quickly after the scan, so the patient is exposed to ionising radiation for only a limited time, while the source remains active long enough for a clear image to be obtained. (c) Use tongs to handle the source at a distance (accept: store sources in lead-lined containers, keep exposure time as short as possible, never point a source at anyone).', '(a) Alpha is the most strongly ionising but least penetrating, stopped by paper or a few centimetres of air; beta is less ionising and more penetrating, stopped by a few millimetres of aluminium; gamma is the least ionising and most penetrating, requiring thick lead or concrete to reduce it significantly. (b) The activity of the tracer falls quickly after the scan, so the patient is exposed to ionising radiation for only a limited time, while the source remains active long enough for a clear image to be obtained. (c) Use tongs to handle the source at a distance (accept: store sources in lead-lined containers, keep exposure time as short as possible, never point a source at anyone).', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_614_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_igphy_nuclear_s3_007_a', 'q_igphy_nuclear_s3_007', 'a', 'Compare the ionising power and penetrating power of alpha, beta and gamma radiation.', '3', 'Alpha is the most strongly ionising but least penetrating, stopped by paper or a few centimetres of air; beta is less ionising and more penetrating, stopped by a few millimetres of aluminium; gamma is the least ionising and most penetrating, requiring thick lead or concrete to reduce it significantly.', '1'),
('sqp_q_igphy_nuclear_s3_007_b', 'q_igphy_nuclear_s3_007', 'b', 'A medical tracer uses an isotope with a half-life of 6 hours. Explain why a short half-life is an advantage for the patient.', '2', 'The activity of the tracer falls quickly after the scan, so the patient is exposed to ionising radiation for only a limited time, while the source remains active long enough for a clear image to be obtained.', '2'),
('sqp_q_igphy_nuclear_s3_007_c', 'q_igphy_nuclear_s3_007', 'c', 'State one safety precaution that should be taken when handling radioactive sources.', '1', 'Use tongs to handle the source at a distance (accept: store sources in lead-lined containers, keep exposure time as short as possible, never point a source at anyone).', '3');
INSERT INTO _migration_614_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_614_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_614_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_614_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_614_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_614_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_614_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_614_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_614_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 7 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_614_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 7 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_614_expected e ON e.id = q.id) = 7 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_614_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
